DROP TABLE IF EXISTS `historial_reasignaciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `historial_reasignaciones` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ticket_id` int NOT NULL,
  `admin_anterior` int DEFAULT NULL,
  `admin_nuevo` int NOT NULL,
  `cambiado_por` int NOT NULL,
  `motivo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_reas_ticket` (`ticket_id`),
  KEY `fk_reas_admin_anterior` (`admin_anterior`),
  KEY `fk_reas_admin_nuevo` (`admin_nuevo`),
  KEY `fk_reas_cambiado_por` (`cambiado_por`),
  CONSTRAINT `fk_reas_admin_anterior` FOREIGN KEY (`admin_anterior`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_reas_admin_nuevo` FOREIGN KEY (`admin_nuevo`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_reas_cambiado_por` FOREIGN KEY (`cambiado_por`) REFERENCES `usuarios` (`id`),
  CONSTRAINT `fk_reas_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

